          ) : (
            <button onClick={() => setShowAddForm('simplex')} className="mt-2 text-sm text-amber-700 hover:text-amber-900 font-medium">
              + Simplex-Frequenz hinzufügen
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

