     3→import { AuthRequest, requireRole } from '../middleware/auth.js';
     4→
     5→export const exercisesRouter = Router();
     6→
     7→// List all exercises with summary stats
     8→exercisesRouter.get('/', (_req, res) => {
     9→  const db = getDb();
    10→  const exercises = db.prepare(`
    11→    SELECT e.id, e.date, e.status, e.notes,
    12→      (SELECT COUNT(DISTINCT operator_id) FROM exercise_attendance WHERE exercise_id = e.id AND is_present = 1) as participant_count,
    13→      (SELECT COUNT(*) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0) as report_count
    14→    FROM exercises e ORDER BY e.date DESC
    15→  `).all();
    16→  res.json(exercises);
    17→});
    18→
    19→// Create exercise (admin only)
    20→exercisesRouter.post('/', requireRole('admin'), (req, res) => {
    21→  const { date, name } = req.body;
    22→  if (!date || !name) {
    23→    res.status(400).json({ error: 'Datum und Name erforderlich' });
    24→    return;
    25→  }
    26→  const db = getDb();
    27→  const result = db.prepare('INSERT INTO exercises (date, name) VALUES (?, ?)').run(date, name);
    28→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(result.lastInsertRowid);
    29→  res.status(201).json(exercise);
    30→});
    31→
    32→// Get full exercise with reports
    33→exercisesRouter.get('/:id', (req, res) => {
    34→  const db = getDb();
    35→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
    36→  if (!exercise) {
    37→    res.status(404).json({ error: 'Übung nicht gefunden' });
    38→    return;
    39→  }
    40→
    41→  const repeaters = db.prepare(`
    42→    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
    43→      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked,
    44→      r.bundesland_code, bl.name as bundesland_name
    45→    FROM exercise_repeaters er
    46→    JOIN repeaters r ON r.id = er.repeater_id
    47→    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
    48→    WHERE er.exercise_id = ?
    49→    ORDER BY r.bundesland_code, r.sort_order
    50→  `).all(req.params.id);
    51→
    52→  const reports = db.prepare(`
    53→    SELECT sr.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code,
    54→      r.short_name as repeater_name,
    55→      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
    56→    FROM signal_reports sr
