    38→
    39→  useEffect(() => {
    40→    apiFetch('/api/v1/reference/bundeslaender').then(setBundeslaender).catch(() => {});
    41→    apiFetch('/api/v1/reference/bezirke').then(setAllBezirke).catch(() => {});
    42→  }, []);
    43→
    44→  useEffect(() => {
    45→    if (repeaters.length > 0 && !activeRepeaterId) {
    46→      setActiveRepeaterId(repeaters[0].repeater_id);
    47→    }
    48→  }, [repeaters, activeRepeaterId]);
    49→
    50→  const activeRepeater = repeaters.find(r => r.repeater_id === activeRepeaterId);
    51→  const repeaterReports = reports.filter(r => r.repeater_id === activeRepeaterId);
    52→
    53→  // Group repeaters by Bundesland
    54→  const repeatersByBl: Record<string, any[]> = {};
    55→  const simplexRepeaters: any[] = [];
    56→  const linkedRepeaters: any[] = [];
    57→  for (const r of repeaters) {
    58→    if (r.type === 'simplex') {
    59→      simplexRepeaters.push(r);
    60→    } else {
    61→      const blCode = r.bundesland_code || '_other';
    62→      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
    63→      repeatersByBl[blCode].push(r);
    64→      if (r.is_linked) linkedRepeaters.push(r);
    65→    }
    66→  }
    67→
    68→  // Sort Bundesland codes
    69→  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    70→    if (a === '_other') return 1;
    71→    if (b === '_other') return -1;
    72→    return a.localeCompare(b);
    73→  });
    74→
    75→  const updateBlOp = async (blCode: string, callsignVal: string) => {
    76→    const blReps = repeatersByBl[blCode] || [];
    77→    for (const r of blReps) {
    78→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${r.repeater_id}`, {
    79→        method: 'PATCH',
    80→        body: JSON.stringify({ operator_callsign: callsignVal || null }),
    81→      });
    82→    }
    83→  };
    84→
    85→  const parseRapport = (raw: string) => {
    86→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    87→    if (!match) return { readability: null, strength: null, db_over_s9: null };
    88→    return {
    89→      readability: parseInt(match[1]),
    90→      strength: parseInt(match[2]),
    91→      db_over_s9: match[3]?.trim() || null,
    92→    };
    93→  };
    94→
    95→  const handleSubmit = async (e: FormEvent) => {
    96→    e.preventDefault();
    97→    if (!selectedOperator || !activeRepeaterId) return;
    98→
    99→    const parsed = parseRapport(rapport);
   100→
   101→    if (editingId) {
   102→      try {
   103→        const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   104→          method: 'PATCH',
   105→          body: JSON.stringify({ ...parsed, notes: notes || null }),
   106→        });
   107→        onReportUpdated(updated);
   108→        setEditingId(null);
   109→      } catch {}
   110→    } else {
   111→      try {
   112→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   113→          method: 'POST',
   114→          body: JSON.stringify({
   115→            operator_id: selectedOperator.id,
   116→            repeater_id: activeRepeaterId,
   117→            ...parsed,
   118→            notes: notes || null,
   119→          }),
   120→        });
   121→        onReportCreated(report);
   122→
   123→        // Cross-repeater sync: create placeholder entries on other repeaters
   124→        for (const rep of repeaters) {
   125→          if (rep.repeater_id !== activeRepeaterId) {
   126→            const exists = reports.some(r => r.operator_id === selectedOperator.id && r.repeater_id === rep.repeater_id);
   127→            if (!exists) {
