     3→import { apiFetch } from '../services/api';
     4→import { useAuth } from '../hooks/useAuth';
     5→
     6→const BUNDESLAENDER = [
     7→  { code: '01', name: 'Wien', label: 'OE1' },
     8→  { code: '02', name: 'Salzburg', label: 'OE2' },
     9→  { code: '03', name: 'Niederösterreich', label: 'OE3' },
    10→  { code: '04', name: 'Burgenland', label: 'OE4' },
    11→  { code: '05', name: 'Oberösterreich', label: 'OE5' },
    12→  { code: '06', name: 'Steiermark', label: 'OE6' },
    13→  { code: '07', name: 'Tirol', label: 'OE7' },
    14→  { code: '08', name: 'Kärnten', label: 'OE8' },
    15→  { code: '09', name: 'Vorarlberg', label: 'OE9' },
    16→];
    17→
    18→export default function ExerciseSetupPage() {
    19→  const { id } = useParams<{ id: string }>();
    20→  const { admin } = useAuth();
    21→  const isAdmin = admin?.role === 'admin';
    22→  const [exercise, setExercise] = useState<any>(null);
    23→  const [allRepeaters, setAllRepeaters] = useState<any[]>([]);
    24→  const [activeRepeaters, setActiveRepeaters] = useState<any[]>([]);
    25→  const [loading, setLoading] = useState(true);
    26→  const [activeBundeslaender, setActiveBundeslaender] = useState<Set<string>>(new Set());
    27→  const [expandedBl, setExpandedBl] = useState<Set<string>>(new Set());
    28→  const [showAddForm, setShowAddForm] = useState<string | null>(null); // bundesland_code or 'simplex'
    29→  const [newRepName, setNewRepName] = useState('');
    30→  const [newRepFreq, setNewRepFreq] = useState('');
    31→  const [newRepOffset, setNewRepOffset] = useState('');
    32→  const [newRepCtcss, setNewRepCtcss] = useState('');
    33→  const [newRepCallsign, setNewRepCallsign] = useState('');
    34→
    35→  useEffect(() => {
    36→    if (!id) return;
    37→    Promise.all([
    38→      apiFetch(`/api/v1/exercises/${id}`),
    39→      apiFetch('/api/v1/repeaters'),
    40→    ]).then(([ex, reps]) => {
    41→      setExercise(ex);
    42→      setAllRepeaters(reps);
    43→      setActiveRepeaters(ex.repeaters || []);
    44→      // Determine which Bundesländer have active repeaters
    45→      const activeBl = new Set<string>();
    46→      for (const er of (ex.repeaters || [])) {
    47→        const rep = reps.find((r: any) => r.id === er.repeater_id);
    48→        if (rep?.bundesland_code) activeBl.add(rep.bundesland_code);
    49→      }
    50→      setActiveBundeslaender(activeBl);
    51→      setExpandedBl(new Set(activeBl));
    52→    }).catch(() => {}).finally(() => setLoading(false));
    53→  }, [id]);
    54→
    55→  const repeatersForBl = (blCode: string) =>
    56→    allRepeaters.filter(r => r.bundesland_code === blCode && r.type !== 'simplex');
    57→
    58→  const simplexRepeaters = allRepeaters.filter(r => r.type === 'simplex');
    59→
    60→  const toggleBundesland = async (blCode: string) => {
    61→    const isActive = activeBundeslaender.has(blCode);
    62→    const newSet = new Set(activeBundeslaender);
    63→    const newExpanded = new Set(expandedBl);
    64→
    65→    if (isActive) {
    66→      // Deactivate all repeaters for this Bundesland
    67→      const blReps = repeatersForBl(blCode);
    68→      for (const rep of blReps) {
    69→        if (activeRepeaters.some(r => r.repeater_id === rep.id)) {
    70→          await apiFetch(`/api/v1/exercises/${id}/repeaters/${rep.id}`, { method: 'DELETE' });
    71→        }
    72→      }
    73→      newSet.delete(blCode);
